/* bop Aero embed: costing-hub
 * Built from components/costing-hub/src/ — DO NOT EDIT THIS FILE.
 * Edit the source and run: python3 tools/build.py costing-hub
 * Embedded on: 
 */
(function () {
  var NAME = "costing-hub";
  var STYLE_ID = 'bopaero-style-' + NAME;
  var CSS = "/* ============================================================================\n   bop Aero embed design tokens \u2014 ONE definition, prepended to every component\n   by tools/build.py. Edit here, rebuild, and both components change together.\n\n   WHY THIS FILE EXISTS: the components previously declared almost no colours or\n   fonts, so every unspecified property silently inherited whatever Squarespace\n   supplied. That produced two customer-facing bugs in one week - orange footnotes\n   and an orange full-size usage note - each fixed one at a time. Tokens make the\n   whole class of bug impossible: nothing is left to inherit by accident.\n\n   Values are MEASURED from bopaero.com computed styles (2026-09-15), not guessed.\n   ========================================================================== */\n.bop-embed {\n  /* brand ------------------------------------------------------------------ */\n  --bop-orange:        #FF6700;\n  --bop-orange-ink:    #fff;\n  /* Derived, so a brand tweak needs one edit. color-mix keeps hover/active in\n     step with --bop-orange instead of drifting as hand-picked hex values. */\n  --bop-orange-hover:  color-mix(in srgb, var(--bop-orange) 88%, #000);\n  --bop-orange-soft:   color-mix(in srgb, var(--bop-orange) 12%, #fff);\n  --bop-navy:          #003767;\n  --bop-ink:           #282D30;\n\n  /* surfaces --------------------------------------------------------------- */\n  /* Raymond 2026-09-18: the calculator now wears the same navy the narrative\n     sections use (measured #003767 on the live pages), so the embed reads as part\n     of the page rather than a tan island in it. The card surface is only one step\n     lighter on purpose - enough to separate, not enough to stripe. */\n  --bop-panel:         #003767;   /* was #E9CEB0 tan */\n  /* Cards carry ALL the structure now. Raymond made the PRICING section the same\n     navy as the panel, so the panel's frame and shadow no longer separate anything\n     and #0A4478 was doing that job at 1.21:1 - which would vanish on a phone in\n     daylight. #0E4D8C is 1.41:1 against the panel: still one family, but each block\n     reads as its own surface. White stays 8.54:1 on it, muted 5.55:1, both AA. */\n  --bop-surface:       #0E4D8C;   /* cards sitting on the panel */\n  --bop-card:          #fff;      /* INPUT fields stay white: legible, and obviously editable */\n  --bop-line:          rgba(255,255,255,.18);\n\n  /* text ------------------------------------------------------------------- */\n  /* Contrast measured against the surface, not guessed: white 9.95:1, muted\n     6.46:1. Orange is 3.41:1 there, which is large-text only - so it is used for\n     buttons and marks, never for body copy. */\n  --bop-text:          #FFFFFF;\n  --bop-text-muted:    #C3D2E2;\n  --bop-label:         #DCE6F1;\n\n  /* type ------------------------------------------------------------------- */\n  --bop-font-head: \"Archivo Black\", \"Arial Black\", system-ui, sans-serif;\n  --bop-font-body: proxima-nova, \"Proxima Nova\", -apple-system, BlinkMacSystemFont,\n                   \"Segoe UI\", Helvetica, Arial, sans-serif;\n  --bop-head-ls:   -0.02em;       /* the site sets a tight negative tracking */\n\n  /* geometry --------------------------------------------------------------- */\n  --bop-radius:      10px;\n  --bop-radius-pill: 300px;       /* site buttons are full pills */\n  --bop-gap:         12px;\n\n  /* feedback --------------------------------------------------------------- */\n  --bop-focus:       var(--bop-navy);\n  --bop-warn-text:   #7a4a00;\n  --bop-warn-bg:     #fff6e5;\n  --bop-warn-edge:   #e8820c;\n\n  --bop-shadow:      0 1px 3px rgba(0,0,0,.10), 0 6px 18px rgba(0,0,0,.06);\n}\n\n/* Motion is opt-out, not opt-in. */\n@media (prefers-reduced-motion: reduce) {\n  .bop-embed *, .bop-embed *::before, .bop-embed *::after {\n    animation-duration: .001ms !important;\n    transition-duration: .001ms !important;\n  }\n}\n\n.bop-hub { font-family: var(--bop-font, inherit); color: var(--bop-ink, #282D30); }\n.bop-hub .hub-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 20px; }\n.bop-hub .hub-card { min-width: 0; background: #fff; border: 1px solid #e3e5e8; border-top: 4px solid var(--bop-orange, #FF6700);\n  border-radius: 8px; padding: 18px 20px; box-shadow: var(--bop-shadow, 0 1px 3px rgba(0,0,0,.1)); }\n.bop-hub h3 { margin: 0 0 2px; font-size: 20px; color: var(--bop-navy, #003767); }\n.bop-hub .hub-sub { margin: 0 0 12px; font-size: 13px; color: #6b6b70; }\n.bop-hub .hub-ver { font-size: 13px; margin: 0 0 4px; }\n.bop-hub .hub-ver b { color: var(--bop-navy, #003767); }\n.bop-hub .hub-note { font-size: 13px; color: #444; margin: 0 0 12px; font-style: italic; }\n.bop-hub table { width: 100%; border-collapse: collapse; font-size: 14px; margin: 4px 0 12px; }\n.bop-hub th { text-align: right; font-size: 12px; color: #6b6b70; font-weight: 600; padding: 4px 6px; border-bottom: 1px solid #e3e5e8; }\n.bop-hub th:first-child, .bop-hub td:first-child { text-align: left; }\n.bop-hub td { text-align: right; padding: 5px 6px; border-bottom: 1px solid #f0f1f3; white-space: nowrap; }\n.bop-hub td:first-child { font-weight: 700; }\n.bop-hub .hub-market { font-size: 13px; padding: 8px 10px; border-radius: 5px; background: #f3f4f6; margin: 0 0 14px; }\n.bop-hub .hub-market.attn { background: var(--bop-warn-bg, #fff6e5); color: var(--bop-warn-text, #7a4a00); border-left: 3px solid var(--bop-warn-edge, #e8820c); }\n.bop-hub .hub-actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }\n.bop-hub .hub-btn { display: inline-block; background: var(--bop-orange, #FF6700); color: #fff !important; text-decoration: none !important;\n  font-weight: 700; font-size: 14px; padding: 9px 16px; border-radius: 5px; }\n.bop-hub .hub-btn:hover { background: var(--bop-orange-hover, #e05a00); }\n.bop-hub .hub-link { font-size: 13px; color: var(--bop-navy, #003767) !important; }\n.bop-hub .hub-err { color: #b91c1c; font-size: 13px; }\n.bop-hub .hub-foot { font-size: 12px; color: #6b6b70; margin: 14px 0 0; }\n/* Phones: the card fits the screen; the table scrolls sideways if it must */\n.bop-hub .hub-tw { overflow-x: auto; -webkit-overflow-scrolling: touch; }\n@media (max-width: 520px) {\n  .bop-hub .hub-card { padding: 14px 14px; }\n  .bop-hub table { font-size: 13px; }\n  .bop-hub th, .bop-hub td { padding: 4px 4px; }\n}\n";
  var HTML = "<!-- Private costing dashboard. Read-only: every figure is fetched live from the\n     published costing; editing happens only in the editors (Cloudflare login). -->\n<div class=\"bop-embed bop-hub\">\n  <div class=\"hub-cards\"></div>\n  <p class=\"hub-foot\">Figures are the published costing, read live. Editing opens the private costing editor in a new tab (Cloudflare login).</p>\n</div>\n";

  function mountPoint() {
    var el = document.getElementById(NAME + '-mount');
    if (el) return el;
    // Fall back to the script's own parent so the stub works even if the
    // mount div is missing or was renamed in the Squarespace block.
    var s = document.currentScript || (function () {
      var all = document.getElementsByTagName('script');
      for (var i = all.length - 1; i >= 0; i--)
        if ((all[i].src || '').indexOf(NAME + '.js') !== -1) return all[i];
      return null;
    })();
    return s && s.parentNode;
  }

  function boot() {
    var m = mountPoint();
    if (!m) { console.warn('[bopaero:' + NAME + '] no mount point found'); return; }
    if (m.getAttribute('data-bopaero-mounted')) return;   // never mount twice
    m.setAttribute('data-bopaero-mounted', '1');

    if (CSS && !document.getElementById(STYLE_ID)) {
      var st = document.createElement('style');
      st.id = STYLE_ID; st.textContent = CSS;
      document.head.appendChild(st);
    }
    m.innerHTML = HTML;

    try {
      component(m);
    } catch (e) {
      console.error('[bopaero:' + NAME + '] component error', e);
    }
  }

  /* ── component source (verbatim from src/component.js) ─────────────── */
  function component(root) {
    /* ============================================================================
       bop Aero embed telemetry — aggregate only, prepended to every component.

       WHAT IT COLLECTS: how far down a page a visit scrolls, where clicks land as a
       coarse grid position, which named control was clicked, and a handful of
       calculator milestones. Plus page path and whether the viewport is phone-sized.

       WHAT IT DOES NOT COLLECT, BY DESIGN: no cookies, no visitor or session id, no
       fingerprint, no form values, no keystrokes, no session replay. Two visits are
       indistinguishable in the data. That is deliberate - it keeps this inside the
       "usage data / network activity" the existing privacy notice already describes,
       so no new processor and no policy redraft. The tracker this replaces (an
       inherited Hotjar) recorded full session replays into an account Raymond did
       not control; the whole point of building our own is not to repeat that.

       Runs ONCE per page even when several embeds are present. Sends nothing until
       ENDPOINT is set, so the data shape can be proven locally first.
       ========================================================================== */
    (function () {
      if (window.__bopTelemetry) return;          // one collector per page

      var ENDPOINT = 'https://bopaero-telemetry.compilotrc.workers.dev/collect';
      var DEBUG = /[?&]bopdebug=1/.test(location.search);
      var GRID_X = 20, GRID_Y = 40;               // click bins: coarse on purpose
      var MILESTONES = [25, 50, 75, 100];

      var events = [];
      var seenScroll = {};
      var sent = false;

      function ctx() {
        return {
          path: location.pathname,
          view: window.innerWidth <= 900 ? 'phone' : 'desktop'
        };
      }
      function push(type, data) {
        if (events.length >= 200) return;         // bound the payload, always
        events.push({ t: type, d: data || {} });
        if (DEBUG) console.log('[bop:telemetry]', type, data || {});
      }

      /* ── scroll depth ──────────────────────────────────────────────────────
         Milestones rather than a continuous position: it answers "how far do
         visitors get" without describing any individual's path down the page. */
      function scrollDepth() {
        var doc = document.documentElement;
        var max = Math.max(1, doc.scrollHeight - window.innerHeight);
        var pct = Math.min(100, Math.round(((window.scrollY || doc.scrollTop || 0) / max) * 100));
        for (var i = 0; i < MILESTONES.length; i++) {
          var m = MILESTONES[i];
          if (pct >= m && !seenScroll[m]) { seenScroll[m] = 1; push('scroll', { pct: m }); }
        }
      }

      /* ── clicks ────────────────────────────────────────────────────────────
         Position is binned to a 20x40 grid of the DOCUMENT, not exact pixels, so
         the report can draw density without the data describing a precise pointer
         trace. `el` names the control when it is one we care about. */
      function describe(node) {
        var el = node;
        for (var i = 0; i < 6 && el && el.nodeType === 1; i++) {
          if (el.id) return '#' + el.id;
          if (el.getAttribute && el.getAttribute('data-embed')) return '[' + el.getAttribute('data-embed') + ']';
          if (el.tagName === 'A' || el.tagName === 'BUTTON' || el.tagName === 'SELECT') {
            var txt = (el.innerText || el.value || '').trim().replace(/\s+/g, ' ').slice(0, 28);
            return el.tagName.toLowerCase() + (txt ? ':' + txt : '');
          }
          el = el.parentElement;
        }
        return 'other';
      }
      function onClick(e) {
        var doc = document.documentElement;
        var w = Math.max(1, doc.scrollWidth), h = Math.max(1, doc.scrollHeight);
        push('click', {
          x: Math.min(GRID_X - 1, Math.floor((e.pageX / w) * GRID_X)),
          y: Math.min(GRID_Y - 1, Math.floor((e.pageY / h) * GRID_Y)),
          el: describe(e.target)
        });
      }

      /* ── delivery ──────────────────────────────────────────────────────────
         sendBeacon on the way out: it survives navigation, where fetch does not.
         visibilitychange fires on mobile where unload often does not. */
      function flush() {
        if (sent || !events.length) return;
        sent = true;
        scrollDepth();          /* final depth before we stop measuring */
        var payload = { v: 1, ctx: ctx(), events: events };
        if (DEBUG) console.log('[bop:telemetry] FLUSH', JSON.stringify(payload));
        if (!ENDPOINT) return;                    // nothing configured: collect, never send
        try {
          /* text/plain, NOT application/json. A non-safelisted content type forces a
             CORS preflight, and sendBeacon cannot perform one - the browser drops the
             request with no error anywhere. It reported "sent" client-side and nothing
             ever arrived. The body is still JSON; the Worker parses it regardless. */
          var blob = new Blob([JSON.stringify(payload)], { type: 'text/plain;charset=UTF-8' });
          if (!navigator.sendBeacon || !navigator.sendBeacon(ENDPOINT, blob)) {
            fetch(ENDPOINT, { method: 'POST', body: blob, keepalive: true, mode: 'no-cors' });
          }
        } catch (e) { /* telemetry must never break the page */ }
      }

      try {
        window.addEventListener('scroll', scrollDepth, { passive: true });
        /* A low-frequency sampler as well as the scroll listener. Scroll events are
           throttled or suppressed entirely in some contexts - background tabs, some
           webviews, and any automated driver - and depth would then silently never
           record. Sampling is cheap, catches programmatic scrolling too, and stops
           as soon as every milestone is seen or the page is on its way out. */
        var sampler = setInterval(function () {
          scrollDepth();
          if (seenScroll[100]) clearInterval(sampler);
        }, 1000);
        document.addEventListener('click', onClick, true);
        document.addEventListener('visibilitychange', function () {
          if (document.visibilityState === 'hidden') flush();
        });
        window.addEventListener('pagehide', flush);
        scrollDepth();

        window.__bopTelemetry = {
          event: function (name, data) { push(name, data); },
          dump: function () { return { ctx: ctx(), events: events }; }
        };
      } catch (e) {
        window.__bopTelemetry = { event: function () {}, dump: function () { return null; } };
        if (DEBUG) console.warn('[bop:telemetry] disabled:', e.message);
      }
    })();

    /* Private costing dashboard (Raymond 2026-10-07).
     *
     * One card per aircraft: the PUBLISHED costing read live (same costing.json and
     * costing.js the documents and calculators use), the latest market check, links
     * to the document and PDF, and an Open editor button. Nothing is editable here:
     * the editors run behind Cloudflare Access and refuse to be framed, and a
     * Squarespace page password is not a substitute for that login.
     */
    var HUB_AIRCRAFT = [
      { name: 'SF50 Vision Jet', sub: 'G3 new · G2+ / G2 / G1 pre-owned',
        site: 'https://sf50program.bopaero.com', pdf: 'bop-Aero-SF50-Ownership-Program-Options.pdf',
        global: 'SF50Costing', repo: 'bopaero/sf50Program', editor: 'https://sf50-costing.compilotrc.workers.dev/' },
      { name: 'SR22T G7+', sub: 'New G7+ GTS · bridge aircraft 2022 G6 GTS',
        site: 'https://sr22tprogram.bopaero.com', pdf: 'bop-Aero-SR22T-Ownership-Program.pdf',
        global: 'SR22TCosting', repo: 'bopaero/sr22tProgram', editor: 'https://sf50-costing.compilotrc.workers.dev/sr22t/' }
    ];

    function initCostingHub(root) {
      var cards = root.querySelector('.hub-cards');
      var minute = Math.floor(Date.now() / 60000);
      function fresh(url) { return url + (url.indexOf('?') < 0 ? '?' : '&') + 'm=' + minute; }
      function money(n) { return '$' + Math.round(n).toLocaleString('en-US'); }
      function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
      function when(iso) {
        var d = new Date(iso);
        return isNaN(d) ? '' : d.toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });
      }
      function loadLib(a) {
        if (window[a.global]) return Promise.resolve(window[a.global]);
        return new Promise(function (resolve, reject) {
          var s = document.createElement('script');
          s.src = fresh(a.site + '/assets/costing.js'); s.async = true; s.setAttribute('data-costing-lib', a.global);
          s.onload = function () { window[a.global] ? resolve(window[a.global]) : reject(new Error('costing.js loaded without ' + a.global)); };
          s.onerror = function () { reject(new Error('costing.js did not load')); };
          document.head.appendChild(s);
        });
      }
      function getJson(url) { return fetch(url, { cache: 'no-cache' }).then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); }); }

      // Market check status line: proposals waiting (SF50), or the information-only value (SR22T bridge)
      function marketLine(m, costing) {
        if (!m) return { cls: '', text: 'Market check: no result yet.' };
        var at = 'checked ' + when(m.checkedAt) + ' (saved when results change)';
        if (m.bridge) {
          var b = m.bridge, paid = costing.bridge && costing.bridge.purchasePrice;
          return { cls: '', text: 'Bridge aircraft market value ≈ ' + (b.marketValue ? money(b.marketValue) : '—') +
            (paid ? ' vs. ' + money(paid) + ' paid' : '') + ' (' + b.count + ' listings). Information only; ' + at + '.' };
        }
        var n = (m.proposals || []).length;
        if (!n) return { cls: '', text: 'Market check: prices match the market; ' + at + '.' };
        return { cls: m.declined ? '' : 'attn', text: n + ' market price proposal' + (n === 1 ? '' : 's') +
          (m.declined ? ' (declined)' : ' waiting for review in the editor') + '; ' + at + '.' };
      }

      HUB_AIRCRAFT.forEach(function (a) {
        var card = document.createElement('section');
        card.className = 'hub-card';
        card.innerHTML = '<h3>' + esc(a.name) + '</h3><p class="hub-sub">' + esc(a.sub) + '</p><div class="hub-body">Loading the published costing…</div>' +
          '<div class="hub-actions"><a class="hub-btn" target="_blank" rel="noopener" href="' + a.editor + '">Open editor</a>' +
          '<a class="hub-link" target="_blank" rel="noopener" href="' + a.site + '/">Document</a>' +
          '<a class="hub-link" target="_blank" rel="noopener" href="' + a.site + '/' + a.pdf + '">PDF</a></div>';
        cards.appendChild(card);
        var body = card.querySelector('.hub-body');

        Promise.all([loadLib(a), getJson(fresh(a.site + '/data/costing.json'))])
          .then(function (r) {
            var lib = r[0], costing = r[1];
            var problems = lib.validate(costing);
            if (problems.length) throw new Error('published costing is invalid: ' + problems.join('; '));
            var d = lib.derive(costing);
            var rows = d.programs.map(function (p) {
              var remaining = typeof p.sharesRemaining === 'number' ? p.sharesRemaining : p.shares;
              return '<tr><td>' + esc(p.key) + '</td><td>' + (p.approx ? '~' : '') + money(p.capPerShare) + '</td><td>' +
                money(p.annualFee) + '</td><td>' + remaining + ' of ' + p.shares + '</td></tr>';
            }).join('');
            body.innerHTML =
              '<p class="hub-ver">Published <b>' + esc(d.version) + '</b> · ' + esc(when(d.publishedAt)) + '</p>' +
              '<p class="hub-note">' + esc(costing.note || '') + '</p>' +
              '<div class="hub-tw"><table><thead><tr><th>Program</th><th>Program Cost</th><th>Annual Fee</th><th>Remaining</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
              '<p class="hub-market">Market check: loading…</p>';
            var mk = body.querySelector('.hub-market');
            // Raw GitHub: the market check saves without republishing the site
            getJson('https://raw.githubusercontent.com/' + a.repo + '/main/data/market.json?m=' + minute)
              .then(function (m) { var l = marketLine(m, costing); mk.textContent = l.text; if (l.cls) mk.classList.add(l.cls); })
              .catch(function (e) { mk.textContent = 'Market check unavailable (' + e.message + ').'; });
          })
          .catch(function (e) {
            body.innerHTML = '<p class="hub-err">Could not read the published costing: ' + esc(e.message) + '</p>';
          });
      });
    }

    /* Plain (non-data) components run this file inside component(root): start here. */
    initCostingHub(root);
  }

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
